// Dynamically assemble directory CTA and related articles links
const input = $('Sub-workflow Intake Trigger').item.json;
const relatedPosts = $items('Search Related Live Articles on WordPress').map(p => ({
  id: p.json.id,
  title: p.json.title?.rendered || 'Legal Article',
  url: p.json.link,
  slug: p.json.slug
})).filter(p => p.url && p.title);

const directoryEntries = $items('Lookup State in Directory Table').map(d => d.json);
const targetState = (input.targetState || 'Federal').trim();
const practiceArea = (input.practiceArea || 'General Law').trim();

const match = directoryEntries.find(d => 
  d.state_name?.toLowerCase() === targetState.toLowerCase() &&
  (d.practice_area?.toLowerCase() === practiceArea.toLowerCase() || d.practice_area?.toLowerCase() === 'all')
);

let hasAttorneys = false;
let ctaHeadline = '';
let ctaSub = '';
let buttonText = '';
let destinationUrl = '';

if (match && (match.has_active_attorneys === 'TRUE' || match.has_active_attorneys === true)) {
  hasAttorneys = true;
  ctaHeadline = match.cta_headline || `Find a Verified ${targetState} ${practiceArea} Attorney`;
  ctaSub = `Connect with top-rated legal counsel in ${targetState} specializing in ${practiceArea}.`;
  buttonText = match.cta_button_text || `Search ${targetState} Directory &rarr;`;
  destinationUrl = match.custom_directory_url || `${$env.WORDPRESS_BASE_URL || 'https://common-law.ai'}/attorneys/?state=${encodeURIComponent(targetState.toLowerCase())}&practice=${encodeURIComponent(practiceArea.toLowerCase())}`;
} else {
  hasAttorneys = false;
  ctaHeadline = 'Need Help with a Legal Matter?';
  ctaSub = `Looking for an experienced attorney in ${targetState}? Get matched with a qualified practitioner today.`;
  buttonText = 'Get Matched With An Attorney &rarr;';
  destinationUrl = `${$env.WORDPRESS_BASE_URL || 'https://common-law.ai'}/get-matched/?state=${encodeURIComponent(targetState.toLowerCase())}`;
}

const ctaHtmlBlock = `
<div class="attorney-directory-cta-widget" style="margin: 35px 0; padding: 25px; background: linear-gradient(135deg, #0f172a, #1e293b); border-radius: 10px; color: #fff; text-align: center; border: 1px solid #334155;">
  <h3 style="margin-top: 0; color: #f8fafc; font-size: 22px;">${ctaHeadline}</h3>
  <p style="color: #94a3b8; font-size: 15px; max-width: 600px; margin: 0 auto 20px auto;">${ctaSub}</p>
  <a href="${destinationUrl}" style="display: inline-block; background-color: #2563eb; color: #fff; padding: 12px 26px; border-radius: 6px; text-decoration: none; font-weight: 600; font-size: 15px;">${buttonText}</a>
</div>
`;

let relatedArticlesBlock = '';
if (relatedPosts.length > 0) {
  relatedArticlesBlock = `
<div class="related-legal-guides" style="margin-top: 30px; padding: 20px; background-color: #f8fafc; border-radius: 8px; border: 1px solid #e2e8f0;">
  <h4 style="margin-top: 0; color: #1e293b;">Related Legal Guides</h4>
  <ul style="margin-bottom: 0; padding-left: 20px;">
    ${relatedPosts.map(p => `<li><a href="${p.url}" style="color: #2563eb; text-decoration: none;">${p.title}</a></li>`).join('')}
  </ul>
</div>
  `;
}

return [{
  json: {
    targetState: targetState,
    practiceArea: practiceArea,
    hasActiveAttorneys: hasAttorneys,
    ctaConfig: {
      headline: ctaHeadline,
      subheadline: ctaSub,
      buttonText: buttonText,
      url: destinationUrl
    },
    ctaHtmlBlock: ctaHtmlBlock,
    relatedPosts: relatedPosts,
    relatedArticlesBlock: relatedArticlesBlock
  }
}];
